```python
import json


def decode_envelope(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    stripped = text.lstrip()
    decoder = json.JSONDecoder()
    data, end = decoder.raw_decode(stripped)

    if not isinstance(data, dict):
        raise TypeError("JSON value must be an object")
    if set(data) != {"token", "values"}:
        raise ValueError("object keys are invalid")
    if not isinstance(data["token"], str):
        raise TypeError("token must be a string")
    if not data["token"]:
        raise ValueError("token must not be empty")
    if not isinstance(data["values"], list):
        raise TypeError("values must be a list")
    if any(type(value) is not int for value in data["values"]):
        raise TypeError("values must contain integers")

    return {"token": data["token"], "values": list(data["values"])}
```

